const u32 *gfx_digitPicture(u8 d)
{
    return digits[d];
}

void gfx_loadBoss(void)
{
    static u32 buffer[16 * 8];
    artToTiles(WALKER, doubledPixel, 4, 4, buffer);
    VDP_loadTileData(buffer, GFX_TILE_BOSS_TOP, 16, CPU);
    artToTiles(WALKER + 16, doubledPixel, 4, 2, buffer);
    VDP_loadTileData(buffer, GFX_TILE_BOSS_BOTTOM, 8, CPU);
}

void gfx_loadDoor(void)
{
    // res/door.png in columns of 6 tiles: a 4 x 4 top sprite then a 4 x 2 bottom one, in hardware order.
    for (u8 c = 0; c < 4; c++)
    {
        VDP_loadTileData(ts_door.tiles + c * 6 * 8, GFX_TILE_BOSS_TOP + c * 4, 4, DMA_QUEUE);
        VDP_loadTileData(ts_door.tiles + (c * 6 + 4) * 8, GFX_TILE_BOSS_BOTTOM + c * 2, 2, DMA_QUEUE);
    }
}

// res/slash.png in columns of 6 tiles: side drawing in 4 columns (4 + 2 tiles), up drawing in 6
// columns (4 tiles used): cut into the guard's sprites (main.c), in hardware column order.
static void loadSlash(void)
{
    const u32 *t = ts_slash.tiles;
    for (u8 c = 0; c < 4; c++)
    {
        VDP_loadTileData(t + c * 6 * 8, GFX_ENEMY_SLASH + c * 4, 4, CPU);
        VDP_loadTileData(t + (c * 6 + 4) * 8, GFX_ENEMY_SLASH + 16 + c * 2, 2, CPU);
    }
    for (u8 c = 0; c < 6; c++)
        VDP_loadTileData(t + (4 + c) * 6 * 8, GFX_ENEMY_SLASH + 24 + c * 4, 4, CPU);
}

void gfx_loadShop(u8 shop)
{
    if (!shop)
    {
        VDP_loadTileSet(&ts_chests, GFX_CHESTS, DMA_QUEUE);
        return;
    }
    // res/shop.png: 12 columns of 8 tiles. Caravan columns 0..7: top 4 tiles then bottom 4, each half
    // (4 columns) one 4 x 4 sprite over another; merchant columns 8..11, tiles 2..7 (4 x 4 + 4 x 2).
    const u32 *t = ts_shop.tiles;
    for (u8 c = 0; c < 8; c++)
    {
        u16 half = GFX_CARAVAN + (c >> 2) * 32 + (c & 3) * 4;
        VDP_loadTileData(t + c * 8 * 8, half, 4, DMA_QUEUE);
        VDP_loadTileData(t + (c * 8 + 4) * 8, half + 16, 4, DMA_QUEUE);
    }
    for (u8 c = 0; c < 4; c++)
    {
        VDP_loadTileData(t + ((8 + c) * 8 + 2) * 8, GFX_MERCHANT + c * 4, 4, DMA_QUEUE);
        VDP_loadTileData(t + ((8 + c) * 8 + 6) * 8, GFX_MERCHANT + 16 + c * 2, 2, DMA_QUEUE);
    }
}

void gfx_load(void)
{
    static u32 buffer[16 * 8];

    PAL_setColor(0, RGB24_TO_VDPCOLOR(0x101028));   // background
    PAL_setColor(1, RGB24_TO_VDPCOLOR(0x442222));
    PAL_setColor(2, RGB24_TO_VDPCOLOR(0x884444));
    PAL_setColor(3, RGB24_TO_VDPCOLOR(0xAA6644));
    PAL_setColor(4, RGB24_TO_VDPCOLOR(0x886622));
    PAL_setColor(5, RGB24_TO_VDPCOLOR(0xCCAA66));
    PAL_setColor(15, RGB24_TO_VDPCOLOR(0xEEEEEE));

    PAL_setColor(16 + 1, RGB24_TO_VDPCOLOR(0x000000));
    PAL_setColor(16 + 2, RGB24_TO_VDPCOLOR(0x222266));
    PAL_setColor(16 + 3, RGB24_TO_VDPCOLOR(0x4444AA));
    PAL_setColor(16 + 4, RGB24_TO_VDPCOLOR(0xEEAA88));
    PAL_setColor(16 + 5, RGB24_TO_VDPCOLOR(0xEE2222));
    PAL_setColor(16 + 6, RGB24_TO_VDPCOLOR(0xEEEEEE));
    PAL_setColor(16 + 15, RGB24_TO_VDPCOLOR(0xEE4444));   // map: boss
    PAL_setColor(32 + 15, RGB24_TO_VDPCOLOR(0xEEEE44));   // map: special rooms, secrets
    PAL_setColor(48 + 15, RGB24_TO_VDPCOLOR(0x664488));   // map: rooms swallowed by the Void

    VDP_loadTileData(SOLID_TILE, GFX_TILE_SOLID, 1, CPU);
    VDP_loadTileData(PLATFORM_TILE, GFX_TILE_PLATFORM, 1, CPU);
    {
        u32 tile[8];
        remapTile(SOLID_TILE, tile);
        VDP_loadTileData(tile, GFX_TILE_SOLID_VOID, 1, CPU);
        remapTile(PLATFORM_TILE, tile);
        VDP_loadTileData(tile, GFX_TILE_PLATFORM_VOID, 1, CPU);
        VDP_loadTileData(VOID_TILE, GFX_TILE_VOID, 1, CPU);
        VDP_loadTileData(CRACKED_TILE, GFX_TILE_CRACKED, 1, CPU);
        remapTile(CRACKED_TILE, tile);
        VDP_loadTileData(tile, GFX_TILE_CRACKED_VOID, 1, CPU);
        VDP_loadTileData(HUD_TILES[0], GFX_TILE_HEART, 7, CPU);
    }
    // Castle tiles. No Void copy: the Void darkens them with the VDP's shadow mode.
    PAL_setColors(0, pal_castle.data, 16, CPU);
    VDP_loadTileSet(&ts_castle, GFX_CASTLE, CPU);
    for (u8 i = 0; i < FAR_RUNS; i++)
        VDP_loadTileData(ts_far.tiles + FAR_RUN[i][0] * 8, FAR_RUN[i][1], FAR_RUN[i][2], CPU);
    PAL_setColors(16, pal_ninja.data, 16, CPU);
    VDP_loadTileSet(&ts_props, GFX_PROPS, CPU);
    VDP_loadTileSet(&ts_chests, GFX_CHESTS, CPU);
    VDP_loadTileSet(&ts_items, GFX_ITEMS, CPU);
    VDP_loadTileSet(&ts_arrow, GFX_ARROWS, CPU);
    loadSlash();
    VDP_loadTileSet(&ts_crate, GFX_CRATE, CPU);
    VDP_loadTileSet(&ts_keys, GFX_KEY, CPU);
    {
        TileSet *font = unpackTileSet(&font_default, NULL);
        memcpy(digits, font->tiles + ('0' - 32) * 8, sizeof(digits));   // the font starts at ' '
        MEM_free(font);
    }
    gfx_loadDecor();


    gfx_loadBoss();
    VDP_loadTileData(SHOT_TILE, GFX_TILE_SHOT, 1, CPU);
    VDP_loadTileData(GEM_TILE, GFX_TILE_GEM, 1, CPU);
    artToTiles(RELIC, plainPixel, 2, 2, buffer);
    VDP_loadTileData(buffer, GFX_TILE_RELIC, 4, CPU);
    VDP_loadTileData(SMALL_TILES[0], GFX_TILE_JELLY_SMALL, 3, CPU);
    VDP_loadTileData(COIN_TILE, GFX_TILE_COIN, 1, CPU);
    artToTiles(JAR, plainPixel, 2, 2, buffer);
    VDP_loadTileData(buffer, GFX_TILE_JAR, 4, CPU);
    artToTiles(HIT_SPARK, plainPixel, 2, 2, buffer);
    VDP_loadTileData(buffer, GFX_TILE_HIT, 4, CPU);
    artToTiles(TRAP_ARROW, plainPixel, 2, 2, buffer);
    VDP_loadTileData(buffer, GFX_TILE_TRAP_ARROW, 4, CPU);
    // Enemies, coins, props and chests share PAL2. PAL3 holds the same slots swallowed by the Void:
    // an enemy in Void form is the same tiles shown with PAL3 (15 = map colour, set above).
    PAL_setColors(32, pal_props.data, 16, CPU);
    PAL_setColors(48, pal_void.data, 15, CPU);

    // Every enemy pose, already in sprite order (tools/art/enemies.py).
    VDP_loadTileSet(&ts_enemies, GFX_ENEMIES, CPU);
}

void gfx_setRoomPalette(u8 inVoid)
{
    static const u32 NORMAL[6] = { 0x101028, 0x442222, 0x884444, 0xAA6644, 0x886622, 0xCCAA66 };
    static const u32 VOIDED[6] = { 0x000000, 0x220044, 0x442266, 0x664488, 0x444466, 0x8888AA };
    const u32 *c = inVoid ? VOIDED : NORMAL;
    for (u8 i = 0; i < 6; i++) PAL_setColor(i, RGB24_TO_VDPCOLOR(c[i]));
}
void gfx_setPlayerCorrupted(u8 corrupted)
{
    if (!corrupted)
    {
        PAL_setColors(16, pal_ninja.data, 16, CPU);
        return;
    }
    PAL_setColor(16 + 2, RGB24_TO_VDPCOLOR(0x440066));
    PAL_setColor(16 + 3, RGB24_TO_VDPCOLOR(0x8822CC));
    PAL_setColor(16 + 5, RGB24_TO_VDPCOLOR(0x44EEEE));
}
u16 gfx_decorTile(u8 i)
{
    return i < DECOR_A_LEN ? GFX_DECOR_A + i : GFX_DECOR_B + i - DECOR_A_LEN;
}

void gfx_loadDecor(void)
{
    u16 n = ts_decor.numTile, a = n < DECOR_A_LEN ? n : DECOR_A_LEN, b = n - a;
    if (b > DECOR_B_LEN) b = DECOR_B_LEN;   // too many: tools/art/outdoor.py must trim the decor
    VDP_loadTileData(ts_decor.tiles, GFX_DECOR_A, a, CPU);
    if (b) VDP_loadTileData(ts_decor.tiles + a * 8, GFX_DECOR_B, b, CPU);
}

void gfx_drawFar(void)
{
    VDP_setTileMapDataRect(FAR_PLANE, FAR_MAP, 0, 0, 64, 32, 64, CPU);
}